def senior(magi,status='single',n=1,year=2026):
 if status=='mfs' or year<2025 or year>2028:return D(0)
 return max(D(0),D(6000)-max(D(0),D(str(magi))-D(150000 if status=='married' else 75000))*D('.06'))*min(n,2)
def deduct(g,status='single',n=0):return D(STD[status])+D(ADD[status])*n+senior(g,status,n)
def bandtax(t,status='single'):
 t=max(D(0),D(str(t)));v=D(0);lo=D(0)
 for top,rate in BANDS[status]:
  hi=t if top is None else min(t,D(top));piece=max(D(0),hi-lo);v+=piece*D(str(rate))
  if top is None or t<=top:break
  lo=D(top)
 return v
def tax(g,status='single',n=0,state=0):
 t=max(D(0),D(str(g))-deduct(g,status,n));return bandtax(t,status)+t*D(str(state))
def marginal(g,status='single',n=0):
 t=max(D(0),D(str(g))-deduct(g,status,n))
 return next(rate for top,rate in BANDS[status] if top is None or t<=top)
def pmt(p,r,n):
 p=D(str(p));r=D(str(r))/12
 return p/n if r==0 else p*r/(1-(1+r)**(-n))
def fv(m,r,n):
 m=D(str(m));r=D(str(r))/12
 return m*n if r==0 else m*((1+r)**n-1)/r
def amort(p,r,payment,maxmonths=10000):
 p=D(str(p));r=D(str(r))/12;payment=D(str(payment));total=D(0);steps=[]
 if p<=0:return {'months':0,'interest':D(0)}
 if payment<=p*r:return {'state':'REFUSES','reason':'Payment does not cover interest; never amortizes'}
 for n in range(1,maxmonths+1):
  interest=p*r;total+=interest;p=p+interest-min(payment,p+interest)
  if p<=0:return {'months':n,'interest':total}
 return {'state':'REFUSES','reason':'Search horizon exhausted; not proof of never'}
