def txeffect(kind,amount,shares=0,price=0,mult=1,fee=0,reinvested=False,direction=None):
 if kind=='buy':return -D(str(shares))*D(str(price))*mult-D(str(fee))
 if kind=='sale':return D(str(shares))*D(str(price))*mult-D(str(fee))
 if reinvested:return D(0)
