def screen_checks(part):
 out=[]
 for f in P[str(part)]['sections'][0]:
  n=int(f['id'].rsplit('-',1)[1]);issues=M_ISSUES.get(n,{})
  for tenet in range(1,9):
   status='PASS';kind='declared_contract';why=''
   if tenet in issues:status='FAIL';kind='specification_issue';why=issues[tenet]
   elif tenet==1:why='The stated arithmetic/source for '+f['label']+' is coherent on complete,valid inputs. Relevant formula-level exceptions remain open;no rendered result was observed.'
   elif tenet==2:why='Declared formula identifies its inputs/parts: '+f['formula']+' Displayed rounding and rendered row reconciliation require implementation evidence.'
   elif tenet==3:
    why='Declared empty/missing behavior: '+f['refusal']
    if (n in [49,53,66] and '0' in f['refusal']) or n in [22,23,55,63]:status='FAIL';kind='coverage_or_assumption_gap';why+=' Missing financial evidence must not be recast as a measured0 or a confirmedbalance.'
   elif tenet==4:why='One declared metric identifier '+f['id']+' and producer '+f['door']+' define the shared concept. Equality of livecallers remains unobserved.'
   elif tenet==5:status='FAIL';kind='evidence_gap';why='A figure declaration cannot establish that edits,sync,imports and recomputation preserve the person’s entered values for '+f['label']+'. No code/test/app was inspected;this is an unclosed evidence requirement,not an observed overwrite.'
   elif tenet==6:
    status='FAIL';kind='evidence_gap';why='The package supplies decision references'+(' and a ruled date '+str(f.get('ruled')) if f.get('ruled') else ',but this row has no ruleddate')+'. Latest approved full drawing/rendered implementation for this exact figure was not independently supplied/inspected;do not infer designcompliance from registration alone.'
   elif tenet==7:why='The declared measure is descriptive under its stated scope;retain estimate/coverage labels and do not turn the number alone into an unsupported recommendation.'
   else:why='Declared words and period are readable for the stated concept: '+f['label']+'. The formula/refusal above gives its context;actual rendered copy remains unobserved.'
   out.append({'figure':f['id'],'tenet':tenet,'verdict':status,'why':why,'finding_kind':kind,'scope':'written declaration only;PASS is not certification of rendered UI','declared_label':f['label']})
 return out
